// ─── Batch 7 | Verify HMAC Signature ─────────────────────────────────────────
// Verifies HMAC-SHA256 signature on the raw webhook body.
// Signature expected in header x-offer-signature: sha256=<hex>
// Computed over raw body bytes using secret from env var OFFER_WEBHOOK_SECRET.
// Uses timing-safe comparison to prevent timing oracle attacks.
// Rejects payloads with requestedAt older than 5 minutes (replay protection).
// Throws on any auth failure — no offer data flows without valid auth.
// ─────────────────────────────────────────────────────────────────────────────

const crypto    = require('crypto');
const inputItem = $input.first();
const item      = inputItem.json;

// ── Raw body: Webhook rawBody:true stores bytes in binary['data'] as base64 ──
const b64     = inputItem.binary?.['data']?.data ?? '';
const rawBody = b64
  ? Buffer.from(b64, 'base64').toString('utf8')
  : JSON.stringify(item.body ?? {});

const headers   = item.headers ?? {};
const sigHeader = String(headers['x-offer-signature'] ?? '').trim();
const secret    = $env['OFFER_WEBHOOK_SECRET'];

if (!sigHeader) {
  throw new Error('Missing x-offer-signature header. Unauthorized request rejected.');
}

if (!secret) {
  throw new Error('OFFER_WEBHOOK_SECRET environment variable not configured.');
}

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');

// ── Timing-safe comparison (prevents timing oracle on secret length) ──
const sigBuf = Buffer.from(sigHeader, 'utf8');
const expBuf = Buffer.from(expected,  'utf8');

let valid = false;
if (sigBuf.length === expBuf.length) {
  valid = crypto.timingSafeEqual(sigBuf, expBuf);
}

if (!valid) {
  throw new Error('HMAC signature mismatch. Unauthorized request rejected.');
}

// ── Parse body after verification ──
const payload = JSON.parse(rawBody);

// ── Replay protection: requestedAt is REQUIRED — reject if absent or expired ──
// Caller must include requestedAt (ISO string) in the JSON body.
if (!payload.requestedAt) {
  throw new Error('Missing requestedAt field. Replay protection requires an ISO timestamp in requestedAt.');
}
const age = Date.now() - new Date(payload.requestedAt).getTime();
if (age > 5 * 60 * 1000) {
  throw new Error('Offer request expired (older than 5 minutes). Replay rejected.');
}

return [{ json: payload }];

// ─── Batch 7 | Normalize Offer Payload ───────────────────────────────────────
// Validates required fields and normalizes offer data types.
// Sets execution context so error handler includes candidate info in Slack alerts.
// Throws on missing required fields — no partial offer proceeds downstream.
// ─────────────────────────────────────────────────────────────────────────────

const item = $input.first().json;

const required = ['candidateName', 'candidateEmail', 'roleApplied', 'offerDetails'];
for (const field of required) {
  if (!item[field]) {
    throw new Error('Missing required field: ' + field + '. Offer payload rejected.');
  }
}

const payload = {
  candidateName:  String(item.candidateName).trim(),
  candidateEmail: String(item.candidateEmail).trim().toLowerCase(),
  roleApplied:    String(item.roleApplied).trim(),
  clientName:     String(item.clientName ?? '').trim() || 'Client',
  offerDetails:   String(item.offerDetails).trim(),
  offeredAt:      new Date().toISOString()
};

$execution.customData.set('candidate_name',  payload.candidateName);
$execution.customData.set('candidate_email', payload.candidateEmail);
$execution.customData.set('role_applied',    payload.roleApplied);
$execution.customData.set('stage',           'offer_gate');

return [{ json: payload }];
